const BluishGreyBaseUniformColourRegex = /#94a5bd;/;
const BluishGreyBaseUniformColour = '#94a5bd;';
const BeigeBaseUniformColour = '#d7b59a;';

export class TmpUniformPack extends BaseNeckProvider implements IUniformPack {
  getUniformSwatches(species: Species) {
    return [
      new Swatch(
        BodyType.AverageMale,
        'Average Male',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageMale,
            ),
            BodyType.AverageMale,
            token,
          ),
        'BodyType.averageMale',
      ),
      new Swatch(
        BodyType.AverageFemale,
        'Average Female',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageFemale,
            ),
            BodyType.AverageFemale,
            token,
          ),
        'BodyType.averageFemale',
      ),
    ];
  }

  getUniformAndVariantBody(token: TokenModel) {
    return this.getUniformAndVariantByBodyType(
      token,
      token.variant,
      token.bodyType,
    );
  }

  getUniformAndVariantByBodyType(
    token: TokenModel,
    variant: UniformVariantType,
    bodyType: BodyType,
  ) {
    let result = '';
    switch (bodyType) {
      case BodyType.AverageMale: {
        if (
          [
            UniformVariantType.Variant2,
            UniformVariantType.Variant3,
            UniformVariantType.Variant4,
          ].includes(variant)
        ) {
          result = TmpUniforms.averageMaleJumpsuitBody;
        } else {
          result = TmpUniforms.averageMaleBody;
        }
        break;
      }
      case BodyType.AverageFemale:
        if (
          [
            UniformVariantType.Variant2,
            UniformVariantType.Variant3,
            UniformVariantType.Variant4,
          ].includes(variant)
        ) {
          result = TmpUniforms.averageFemaleJumpsuitBody;
        } else {
          result = TmpUniforms.averageFemaleBody;
        }
        break;
      default:
    }
    if (
      [
        UniformVariantType.Variant1,
        UniformVariantType.Variant2,
        UniformVariantType.Variant4,
      ].includes(variant)
    ) {
      result = result.replace(
        BluishGreyBaseUniformColourRegex,
        this.getUniformBaseColour(variant, token),
      );
    }

    if (this.isSecurity(token) && variant === UniformVariantType.Variant2) {
      if (token.bodyType === BodyType.AverageMale) {
        result = result + TmpUniforms.averageMaleSecurityVest;
      } else {
        result = result + TmpUniforms.averageFemaleSecurityVest;
      }
    }

    return (
      this.getNeck(
        bodyType,
        token.skinColor,
        token.species,
        UniformEra.TheMotionPicture,
      ) +
      result
        .replace(DefaultRed, token.divisionColor)
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor)
    );
  }

  getUniformVariantSwatches(token: TokenModel) {
    const result = [
      new Swatch(UniformVariantType.Base, 'Base', (token) =>
        UniformCatalog.decorateSwatch(
          this.getUniformAndVariantByBodyType(
            token,
            UniformVariantType.Base,
            token.bodyType,
          ),
          UniformVariantType.Base,
          token,
        ),
      ),
      new Swatch(UniformVariantType.Variant1, 'Beige Variant', (token) =>
        UniformCatalog.decorateSwatch(
          this.getUniformAndVariantByBodyType(
            token,
            UniformVariantType.Variant1,
            token.bodyType,
          ),
          UniformVariantType.Variant1,
          token,
        ),
      ),
    ];
    result.push(
      new Swatch(UniformVariantType.Variant3, 'Jumpsuit Variant', (token) =>
        UniformCatalog.decorateSwatch(
          this.getUniformAndVariantByBodyType(
            token,
            UniformVariantType.Variant3,
            token.bodyType,
          ),
          UniformVariantType.Variant3,
          token,
        ),
      ),
    );
    result.push(
      new Swatch(
        UniformVariantType.Variant4,
        'Beige Jumpsuit Variant',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Variant4,
              token.bodyType,
            ),
            UniformVariantType.Variant4,
            token,
          ),
      ),
    );
    if (this.isSecurity(token)) {
      result.push(
        new Swatch(UniformVariantType.Variant2, 'Security Variant', (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Variant2,
              token.bodyType,
            ),
            UniformVariantType.Variant2,
            token,
          ),
        ),
      );
    }
    return result;
  }

  private isSecurity(token: TokenModel) {
    return (
      DivisionColors.getDivision(
        UniformEra.TheMotionPicture,
        token.divisionColor,
      ) === 'Security'
    );
  }

  getRankSwatches() {
    return [
      new Swatch(
        Rank.None,
        'None',
        (token) => TmpUniformPack.decorateRankSwatch('', Rank.None, token),
        'Rank.none.name',
      ),
      new Swatch(
        Rank.Ensign,
        'Ensign',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Ensign.replace(
              BluishGreyBaseUniformColourRegex,
              this.getUniformBaseColour(token.variant, token),
            ),
            Rank.Ensign,
            token,
          ),
        'Rank.ensign.name',
      ),
      new Swatch(
        Rank.LieutenantJG,
        'Lieutenant J.G.',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.LieutenantJG.replace(
              BluishGreyBaseUniformColourRegex,
              this.getUniformBaseColour(token.variant, token),
            ),
            Rank.LieutenantJG,
            token,
          ),
        'Rank.lieutenantJG.name',
      ),
      new Swatch(
        Rank.Lieutenant,
        'Lieutenant',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Lieutenant.replace(
              BluishGreyBaseUniformColourRegex,
              this.getUniformBaseColour(token.variant, token),
            ),
            Rank.Lieutenant,
            token,
          ),
        'Rank.lieutenant.name',
      ),
      new Swatch(
        Rank.LtCommander,
        'Lt. Commander',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.LtCommander.replace(
              BluishGreyBaseUniformColourRegex,
              this.getUniformBaseColour(token.variant, token),
            ),
            Rank.LtCommander,
            token,
          ),
        'Rank.ltCommander.name',
      ),
      new Swatch(
        Rank.Commander,
        'Commander',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Commander.replace(
              BluishGreyBaseUniformColourRegex,
              this.getUniformBaseColour(token.variant, token),
            ),
            Rank.Commander,
            token,
          ),
        'Rank.commander.name',
      ),
      new Swatch(
        Rank.Captain,
        'Captain',
        (token) =>
          TmpUniformPack.decorateRankSwatch(
            TmpRankIndicators.swatches.Captain.replace(
              BluishGreyBaseUniformColourRegex,
              this.getUniformBaseColour(token.variant, token),
            ),
            Rank.Captain,
            token,
          ),
        'Rank.captain.name',
      ),
    ];
  }

  getRankIndicator(token: TokenModel) {
    if (
      [UniformVariantType.Variant3, UniformVariantType.Variant4].includes(
        token.variant,
      )
    ) {
      const rank = Rank[token.rankIndicator];
      if (token.bodyType === BodyType.AverageFemale) {
        return TmpRankIndicators.epaulette.AverageFemale[rank] ?? '';
      } else {
        return TmpRankIndicators.epaulette.AverageMale[rank] ?? '';
      }
    } else {
      return '';
    }
  }

  private getUniformBaseColour(variant: UniformVariantType, token: TokenModel) {
    let baseColour = BluishGreyBaseUniformColour;
    if (variant === UniformVariantType.Variant1) {
      baseColour = BeigeBaseUniformColour;
    } else if (
      variant === UniformVariantType.Variant2 &&
      this.isSecurity(token)
    ) {
      baseColour = BeigeBaseUniformColour;
    } else if (variant === UniformVariantType.Variant4) {
      baseColour = BeigeBaseUniformColour;
    }
    return baseColour;
  }

  getRankBorderIndicator(token: TokenModel) {
    let result = '';
    switch (token.rankIndicator) {
      case Rank.Ensign:
        result = TmpRankIndicators.border.Ensign;
        break;
      case Rank.LieutenantJG:
        result = TmpRankIndicators.border.LieutenantJG;
        break;
      case Rank.Lieutenant:
        result = TosLieutenantBorder;
        break;
      case Rank.LtCommander:
        result = TosLtCommanderBorder;
        break;
      case Rank.Commander:
        result = TosCommanderBorder;
        break;
      case Rank.Captain:
        result = TosCaptainBorder;
        break;
      default:
    }
    return result.replace(
      BluishGreyBaseUniformColourRegex,
      this.getUniformBaseColour(token.variant, token),
    );
  }

  getBorderColor(token: TokenModel) {
    return token.divisionColor;
  }

  getRankBorderDefinitions(token: TokenModel, bordered: boolean) {
    return '';
  }

  static decorateRankSwatch(
    svg: string,
    rankIndicator: Rank,
    token: TokenModel,
  ) {
    return (
      `<svg viewBox="0 0 80 80" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
            <defs>
                <clipPath id="rankClipPath` +
      rankIndicator +
      `">
                    <circle cx="40" cy="40" r="40" fill="#ffffff" />
                </clipPath>
            </defs>
            <g clip-path="url(#rankClipPath` +
      rankIndicator +
      `">
                <g transform="translate(-65, -318)">` +
      svg.replace(DefaultRed, '#94a5bd') +
      `</g>
        + </g>
        </svg>`
    );
  }

  getBorderLogo(token: TokenModel): string {
    return TmpDelta.replace(DefaultRed, token.divisionColor);
  }

  isDivisionColorSupported(token: TokenModel): boolean {
    return true;
  }

  getRankIndicatorExtra(token: TokenModel): string {
    return '';
  }
}
